"""Verify that this checkout contains the delivered controlled 4T4R sources."""
from pathlib import Path
import hashlib
import json

project = Path(__file__).resolve().parents[1]
sdk = project / 'X2100_project-main/firmware/x2100/freertos'
record = json.loads((project / 'docs/source4t4r_controlled_20261020.json').read_text())
checked = 0
for name, expected in record['source_sha256'].items():
    path = sdk / name
    if name == '.config.in':
        path = sdk / record['configuration_template']
    elif name == 'build/build.lds.in':
        # Generated by make from the tracked linker input template.
        continue
    raw = path.read_bytes()
    assert hashlib.sha256(raw.replace(b'\r\n', b'\n')).hexdigest() == expected, name
    checked += 1
print('PASS:', checked, 'controlled 4T4R source/config inputs; generated linker file excluded')
